'use strict';
(()=>{
const C=window.ESPEJO,CFG=window.ESPEJO_CONFIG||{},KEY='ludaria_espejo_compartido_v1',$=(s,r=document)=>r.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const blank=()=>({version:1,page:0,visited:[0],fields:{},levels:{},fragment:false});
let state=blank();try{const s=JSON.parse(localStorage.getItem(KEY));if(s&&s.version===1)state={...blank(),...s,fields:{...(s.fields||{})},levels:{...(s.levels||{})}}}catch(_){}
let seconds=300,ticker=null;
const stage=$('#stage'),modal=$('#modal'),body=$('#modal-body'),toast=$('#toast');
const save=()=>{localStorage.setItem(KEY,JSON.stringify(state));hud()};
const field=id=>state.fields[id]||'';
const notify=m=>{toast.textContent=m;toast.hidden=false;clearTimeout(notify.t);notify.t=setTimeout(()=>toast.hidden=true,2600)};
const meta=()=>C.pages[state.page];
const product=()=>`<p class="product"><strong>Producto:</strong> ${esc(meta().product)}</p>`;
const heading=(tag,title,lead='')=>`<div class="section-title"><div><span class="eyebrow">${esc(tag)}</span><h2>${esc(title)}</h2>${lead?`<p class="lead">${esc(lead)}</p>`:''}</div><span class="time-label">${meta().time} min</span></div>`;
const textarea=(id,wide=false)=>{const f=C.fields[id];return `<label class="field${wide?' wide':''}">${esc(f.label)}<textarea data-field="${id}" placeholder="${esc(f.placeholder)}">${esc(field(id))}</textarea></label>`};
function cover(){return `<section class="scene"><div class="cover-content"><span class="eyebrow">MISIÓN SECUNDARIA · SESIÓN 13 · CIERRE DEL MÓDULO 4</span><h1 class="cover-title">El Espejo <span>Compartido</span></h1><p class="lead">Comunica tu diseño, defiende decisiones con evidencia y recibe una última mirada antes de la defensa del Orbe.</p><div class="cover-meta"><span class="small-line"></span><span>90 min sincrónicos · sin carga autónoma</span></div><blockquote class="mentor">“Una mirada compartida no sustituye tu criterio: lo vuelve visible y discutible.”<small>GUARDIANA MIRA</small></blockquote><div class="actions"><button class="button" data-go="1">Abrir el espejo</button><button class="button secondary" data-action="resources">Recursos</button></div><p class="note">El facilitador organiza el orden real. Esta página no asigna participantes ni envía retroalimentación.</p></div></section>`}
function model(){return `<section class="scene"><div class="scene-content wide">${heading('PASO 1 · ESTRUCTURAR','Una defensa en cinco minutos',meta().prompt)}<div class="defense-grid"><article class="defense-card"><span class="num">1</span><h3>Propósito y contexto</h3><p>¿Qué aprendizaje orienta el diseño y para quién fue pensado?</p></article><article class="defense-card"><span class="num">2</span><h3>Decisiones defendibles</h3><p>Elige dos decisiones y señala dónde se observan en el prototipo.</p></article><article class="defense-card"><span class="num">3</span><h3>Implementación y pregunta</h3><p>Resume las condiciones y abre un aspecto a la mirada del grupo.</p></article></div><div class="feedback">La exposición hace visibles decisiones y evidencias. No necesita enumerar cada componente del prototipo.</div>${product()}</div></section>`}
function prepare(){return `<section class="scene"><div class="scene-content wide">${heading('PASO 2 · PREPARAR','Preparar la mirada',meta().prompt)}<div class="presentation-fields">${textarea('project')}${textarea('audience')}${textarea('purpose',true)}${textarea('decision1')}${textarea('evidence1')}${textarea('decision2')}${textarea('evidence2')}${textarea('implementation')}${textarea('question')}</div>${product()}</div></section>`}
function timerText(){return `${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`}
function round(){return `<section class="scene"><div class="scene-content wide">${heading('PASO 3 · PRESENTAR','Ronda de presentaciones',meta().prompt)}<div class="timer-stage"><div class="mirror-timer${ticker?' running':''}"><span class="eyebrow">TEMPORIZADOR OPCIONAL</span><output id="timer" aria-live="polite">${timerText()}</output><div class="actions"><button class="button small" data-action="timer-toggle">${ticker?'Pausar':'Iniciar'}</button><button class="button secondary small" data-action="timer-reset">Reiniciar</button></div><p class="note">No avanza pantallas ni registra asistencia.</p></div><div class="speaker-card">${textarea('speaker')}${textarea('note')}<div class="feedback hint">Orden sugerido para escuchar: propósito → decisión → evidencia → condición de implementación → pregunta. El facilitador adapta el bloque al número real de participantes.</div></div></div>${product()}</div></section>`}
function feedback(){return `<section class="scene"><div class="scene-content wide">${heading('PASO 4 · DEVOLVER','Retroalimentación cruzada',meta().prompt)}${textarea('peer',true)}<div class="rubric-compact">${C.criteria.map((c,i)=>`<div class="rubric-line"><strong>${i+1} · ${esc(c)}</strong>${C.levels.map((l,j)=>`<button data-level="${j}" data-criterion="${i}" aria-pressed="${state.levels[i]===j}">${esc(l)}</button>`).join('')}</div><label class="sr-only" for="comment-${i}">Comentario del criterio ${i+1}</label><textarea id="comment-${i}" data-field="comment_${i}" placeholder="Comentario breve con evidencia para el criterio ${i+1}">${esc(field(`comment_${i}`))}</textarea>`).join('')}</div><div class="feedback-card">${textarea('strength')}${textarea('suggestion')}</div><p class="source-note">Pauta exacta del Anexo H reutilizada como apoyo. El anexo declara su aplicación en sesiones 10 y 11; aquí no se convierte en una nueva calificación.</p>${product()}</div></section>`}
function respond(){return `<section class="scene"><div class="scene-content wide">${heading('PASO 5 · DECIDIR','Lo que defiendo y lo que reviso',meta().prompt)}<div class="received-grid">${textarea('received')}${textarea('response')}${textarea('next')}</div><div class="feedback">Registrar una sugerencia no obliga a aceptarla. La persona autora decide qué conserva o cambia y deja una razón explícita.</div><div class="actions"><button class="button" data-action="notebook">Revisar bitácora</button><button class="button secondary" data-action="download">Descargar registro .txt</button><button class="button secondary" data-action="copy">Copiar registro</button></div>${product()}</div></section>`}
function fragment(){return `<section class="scene"><div class="scene-content wide"><div class="fragment-stage"><div>${heading('CIERRE · FRAGMENTO IV','El cuarto fragmento',meta().prompt)}<p class="lead">Después de las presentaciones y la retroalimentación, participa en la recuperación del último fragmento.</p><div class="actions"><button class="button" data-action="fragment">${state.fragment?'Fragmento recuperado':'Facilitador: revelar fragmento'}</button><button class="button secondary" data-action="notebook">Conservar registro</button></div><p class="note">La revelación es narrativa y local. No verifica entregas ni modifica sistemas externos.</p></div><div class="fragment-visual${state.fragment?' revealed':''}" aria-label="${state.fragment?'Cuarto fragmento revelado':'Silueta del cuarto fragmento'}"><div class="fragment-piece"></div></div></div>${state.fragment?'<div class="feedback">Fragmento IV recuperado. El Santuario queda completo y la Bóveda del Orbe será el próximo destino.</div>':''}${product()}</div></section>`}
const screens=[cover,model,prepare,round,feedback,respond,fragment];
function hud(){$('#seal-status').innerHTML=C.criteria.map((_,i)=>`<span class="seal-dot${state.levels[i]!==undefined?' solved':''}" title="Criterio ${i+1}">${state.levels[i]!==undefined?'✓':i+1}</span>`).join('')}
function render(){state.page=Math.max(0,Math.min(screens.length-1,state.page));state.visited=[...new Set([...(state.visited||[]),state.page])];save();document.body.classList.toggle('is-cover',state.page===0);stage.innerHTML=screens[state.page]();$('#previous').disabled=state.page===0;$('#next').disabled=state.page===screens.length-1;$('#next-label').textContent=state.page===screens.length-2?'Cerrar módulo':'Siguiente';$('#page-count').textContent=`${state.page+1} / ${screens.length}`;$('#route-dots').innerHTML=C.pages.map((p,i)=>`<button class="route-dot${state.visited.includes(i)?' visited':''}${state.page===i?' current':''}" data-go="${i}" aria-label="Ir a ${esc(p.title)}" aria-current="${state.page===i?'page':'false'}"></button>`).join('');hud();stage.focus({preventScroll:true})}
function record(){const a=['LUDARIA · EL ESPEJO COMPARTIDO','Registro local de presentación y retroalimentación',''];['project','audience','purpose','decision1','evidence1','decision2','evidence2','implementation','question'].forEach(id=>a.push(`${C.fields[id].label}: ${field(id)||'—'}`));a.push('','PAUTA DE APOYO · ANEXO H',`Diseño revisado: ${field('peer')||'—'}`);C.criteria.forEach((c,i)=>a.push(`${i+1}. ${c}\nNivel: ${state.levels[i]!==undefined?C.levels[state.levels[i]]:'—'}\nComentario: ${field(`comment_${i}`)||'—'}`));['strength','suggestion','received','response','next'].forEach(id=>a.push(`${C.fields[id].label}: ${field(id)||'—'}`));a.push('','Nota: registro descriptivo sin puntos, promedio, envío ni recepción simulada.');return a.join('\n')}
function show(html){body.innerHTML=html;modal.showModal()}
function map(){show(`<h2 id="modal-title">Índice de la sesión</h2><p>Todas las pantallas permanecen disponibles para consultar el recorrido.</p><div class="modal-grid">${C.pages.map((p,i)=>`<button class="map-item${i===state.page?' current':''}" data-go="${i}"><span>${i+1}</span>${esc(p.title)} · ${p.time} min</button>`).join('')}</div>`)}
function sources(){show(`<h2 id="modal-title">Fuentes y límites</h2>${C.sources.map(s=>`<article class="panel"><h3>${esc(s.title)}</h3><p>${esc(s.apa)}</p>${s.url?`<p><a href="${esc(s.url)}" target="_blank" rel="noopener">Abrir fuente primaria</a></p>`:''}<p class="note">${esc(s.use)}</p></article>`).join('')}`)}
function resources(){const x=[['Prototipo',CFG.prototipoExterno,'Usa la versión local o archivo que ya preparaste.'],['Plantilla',CFG.plantillaExterna,'La plantilla editable está integrada en la pantalla 3.'],['Canal de retroalimentación',CFG.canalRetroalimentacion,'Copia o descarga el registro y compártelo por el canal real indicado.']];show(`<h2 id="modal-title">Recursos</h2><p>Los enlaces externos son opcionales; las alternativas locales permiten conducir la sesión.</p>${x.map(([n,u,f])=>`<article class="panel"><h3>${n}</h3>${u?`<p><a href="${esc(u)}" target="_blank" rel="noopener">Abrir recurso configurado</a></p>`:`<p>${esc(f)}</p><span class="pill">Alternativa local disponible</span>`}</article>`).join('')}`)}
function notebook(){show(`<h2 id="modal-title">Bitácora del espejo</h2><p>Este registro permanece en este navegador y no se envía automáticamente.</p><label class="field">Registro reunido<textarea id="record" readonly style="min-height:340px">${esc(record())}</textarea></label><div class="actions"><button class="button" data-action="download">Descargar .txt</button><button class="button secondary" data-action="copy">Copiar</button><button class="text-button" data-action="reset-dialog">Borrar datos locales…</button></div>`)}
function download(){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([record()],{type:'text/plain;charset=utf-8'}));a.download='registro-el-espejo-compartido.txt';a.click();URL.revokeObjectURL(a.href);notify('Registro descargado.')}
async function copy(){try{await navigator.clipboard.writeText(record());notify('Registro copiado.')}catch(_){const r=$('#record');if(r){r.select();notify('Texto seleccionado: usa copiar.')}else notebook()}}
function timerToggle(){if(ticker){clearInterval(ticker);ticker=null;render();return}if(seconds<=0)seconds=300;ticker=setInterval(()=>{seconds--;const o=$('#timer');if(o)o.textContent=timerText();if(seconds<=0){clearInterval(ticker);ticker=null;notify('Cinco minutos cumplidos. El facilitador decide el siguiente paso.');render()}},1000);render()}
document.addEventListener('input',e=>{if(e.target.matches('[data-field]')){state.fields[e.target.dataset.field]=e.target.value;save()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.action;if(b.dataset.go!==undefined){state.page=Number(b.dataset.go);modal.close();render();return}if(b.dataset.level!==undefined){state.levels[b.dataset.criterion]=Number(b.dataset.level);save();render();return}if(a==='close')modal.close();else if(a==='map')map();else if(a==='sources')sources();else if(a==='resources')resources();else if(a==='notebook')notebook();else if(a==='download')download();else if(a==='copy')copy();else if(a==='fullscreen'){if(!document.fullscreenElement)document.documentElement.requestFullscreen?.();else document.exitFullscreen?.()}else if(a==='timer-toggle')timerToggle();else if(a==='timer-reset'){if(ticker){clearInterval(ticker);ticker=null}seconds=300;render()}else if(a==='fragment'){state.fragment=true;save();render();notify('Fragmento IV revelado en este dispositivo.')}else if(a==='reset-dialog')show('<h2 id="modal-title">Borrar datos locales</h2><p>Elimina el guion, la pauta y la bitácora de este navegador. Descarga antes si quieres conservarlos.</p><div class="actions"><button class="button" data-action="reset-confirm">Borrar</button><button class="button secondary" data-action="close">Cancelar</button></div>');else if(a==='reset-confirm'){localStorage.removeItem(KEY);state=blank();seconds=300;modal.close();render();notify('Datos locales borrados.')}});
$('#previous').addEventListener('click',()=>{if(state.page>0){state.page--;render()}});$('#next').addEventListener('click',()=>{if(state.page<screens.length-1){state.page++;render()}});
document.addEventListener('keydown',e=>{if(modal.open||/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(e.key==='ArrowRight'&&state.page<screens.length-1){state.page++;render()}if(e.key==='ArrowLeft'&&state.page>0){state.page--;render()}});
modal.addEventListener('click',e=>{if(e.target===modal)modal.close()});
for(let i=0;i<18;i++){const f=document.createElement('i');f.className='fly';f.style.left=`${(i*37)%97}%`;f.style.top=`${(i*53)%88}%`;f.style.animationDelay=`-${i%9}s`;$('#fireflies').append(f)}
render();
})();


